function validate(input) {
  const [{ Customers = [], Product = [], Orders = [] }] = input;
  const customers = new Set(), products = new Set(), orders = new Set();
  for (const [id, name] of Customers) {
    if (id === null || name === null) return 'Every customer needs a customer_id and a name.';
    if (customers.has(id)) return `customer_id ${id} appears twice in Customers.`;
    customers.add(id);
  }
  for (const [id, , price] of Product) {
    if (id === null || price === null) return 'Every product needs a product_id and a price.';
    if (products.has(id)) return `product_id ${id} appears twice in Product.`;
    if (price < 0) return 'price cannot be negative.';
    products.add(id);
  }
  for (const [id, customer, product, date, quantity] of Orders) {
    if (id === null || customer === null || product === null || date === null || quantity === null) return 'Orders values cannot be null.';
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    orders.add(id);
    if (!customers.has(customer)) return `Order ${id} names unknown customer ${customer}.`;
    if (!products.has(product)) return `Order ${id} names unknown product ${product}.`;
    if (quantity < 1) return 'quantity must be at least 1.';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return `order_date ${date} is not YYYY-MM-DD.`;
  }
  return null;
}

