function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const small = size === 'small';
  const names = ['Winston', 'Jonathan', 'Moustafa', 'Ana', 'Ravi', 'Sofia'];
  const countries = ['USA', 'Peru', 'Egypt', 'India'];
  const prices = [0, 2, 10, 45, 50, 60, 100, 300];
  const customerCount = small ? pick(5) : 400, productCount = small ? pick(5) : 100;
  const Customers = [], Product = [], Orders = [];
  for (let id = 1; id <= customerCount; id++) Customers.push([id, names[pick(names.length)], countries[pick(countries.length)]]);
  for (let id = 1; id <= productCount; id++) Product.push([id * 10, `Item ${id}`, prices[pick(prices.length)]]);
  const smallDates = ['2020-05-31', '2020-06-01', '2020-06-15', '2020-06-30', '2020-07-01', '2020-07-20', '2020-07-31', '2020-08-01', '2019-06-10', '2021-07-10'];
  const day = k => new Date(Date.UTC(2020, 3, 1) + k * 86400000).toISOString().slice(0, 10);
  const orderCount = customerCount && productCount ? (small ? pick(9) : 2000) : 0;
  for (let id = 1; id <= orderCount; id++) {
    const date = small ? smallDates[pick(smallDates.length)] : rand() < 0.1 ? `${2019 + 2 * pick(2)}-0${6 + pick(2)}-1${pick(10)}` : day(pick(180));
    Orders.push([id, 1 + pick(customerCount), 10 * (1 + pick(productCount)), date, 1 + pick(3)]);
  }
  return [{ Customers, Product, Orders }];
}
